INSERT INTO `t_pro_info` VALUES (16, 'c103a601-e41b-4318-9b4a-9a5a75ff6a7a', NULL, '1. 国家自然科学基金面上项目，NF-κB信号通路数学建模及其在多发性骨髓瘤骨病发病机制中应用研究，2022/01-2025/12，57万元，在研，负责人\n\n2. 国家自然科学基金面上项目，恶性肿瘤转移性骨病发病机理生物数学建模及疗法预测评价方法研究，2017/01-2020/12，62万元，结题，负责人\n\n3. 科技部重点研发计划课题，多肢体协调控制与辅助作业策略研究，2019/01-2021/12，182万，在研，负责人\n\n4. 中央军委科技委创新特区项目，***关键技术，80万，2019/08-2020/08，结题，负责人\n\n5. 国家自然科学基金青年项目，多发性骨髓瘤骨病形成过程数学建模及治疗方法模拟评测研究，2014/01-2016/12，23万元，结题，负责人\n\n6. 国家高端外国专家项目，基于传统中药提取新型抗菌药物创新方法研究，2019/01-2019/12，14万，结题，负责人', 1.00);
INSERT INTO `t_pro_info` VALUES (17, '7ff36c9b-6578-4d0e-890f-b69ae50ad249', 2, 'Ø 中国优选法统筹法与经济数学研究会灰色系统专业委员会理事\nØ 中国物流学会会员\nØ 中国太平洋学会东北亚日本海研究分会理事\nØ SCI期刊Grey   Systems: Theory and Application编委\nØ Journal of the Operational   Research Society、International Journal of Production Research、Journal   of cleaner production、Journal of Information Science   and Engineering等SSCI/SCI期刊审稿人', 4.00);
INSERT INTO `t_pro_info` VALUES (18, '7884f47f-3099-4d29-b602-2ddff13a07ea', NULL, '蒋鹏，男，1987年10月出生，企业管理学博士，应用经济学博士后，现为山东大学商学院供应链管理专业教师，硕士生导师。中国优选法统筹法与经济数学研究会灰色系统专业委员会理事、中国太平洋学会东北亚日本海研究分会理事，并担任国际期刊Journal of Management and Decision Sciences执行编辑，SCI收录期刊Grey Systems: Theory and Applications 编委会委员，Journal of the Operational Research Society、International Journal of Production Research、Journal of cleaner production、Journal of Information Science and Engineering等SSCI/SCI期刊审稿人。主要研究方向为：多属性决策、物流与供应链管理、灰色系统理论等。', 1.00);
INSERT INTO `t_pro_info` VALUES (19, '0ef2dbff-4445-4004-af11-bad361456731', NULL, '2016-09-01    优秀本科生导师；\n2015-09-01    优秀本科生导师；\n2014-10-01    优秀本科生导师；\n2013-06-20    “桃李杯”毕业生最喜爱老师；\n2012-06-20    ”桃李杯“毕业生最喜爱老师；', 1.00);
INSERT INTO `t_pro_info` VALUES (22, '5ceb63b0-8705-4823-bf4e-fbaeae18848b', NULL, '历年指导的学生团队在ACM、齐鲁软件设计大赛、“挑战杯”、“蓝桥杯”、“发现杯”“中科软杯”等各种软件设计大赛中获得多项奖励；2011年被评为山东大学优秀共产党员；2012山东大学优秀教研成果奖；多次获评研究生“我最喜爱的导师”和本科生“最受欢迎的专业课老师”。\n科研项目\n1、国家自然科学基金项目《知识库更新理论与算法研究》（69873027）；\n2、《基因组重组进化树问题的算法及复杂性》（60073042）；\n3、国家863－306主题《NP问题及其实用快速算法》（863－306－ZT06-01）；\n4、《跨机构服务组合的应用一致性研究》（60903052）；\n5、《企业Intranet向网格环境迁移的技术与应用研究》（J06L75）；\n6、教育部“十一五”子课题《培养软件与服务外包人才的校内实训模式研究》（FIB070335-A8-16）；\n7、威海市科技局《云社区医疗卫生信息管理系统》；\n8、主持2013年山东省自然科学基金项目《面向自治计算的虚拟化环境下资源管理策略研究》', 1.00);
INSERT INTO `t_pro_info` VALUES (23, '7c1a821e-41ba-415c-9ce4-c293edf1fc40', NULL, '热爱帮助他人', 1.00);
INSERT INTO `t_pro_info` VALUES (24, '5f6fdaad-e212-4530-b227-e2e992dd01b7', NULL, NULL, NULL);
